mapper.select:
WITH RECURSIVE trace_tree AS ( -- 锚点：起始节点（level=1） SELECT id, node_type, node_code, parent_id, batch_id, qty_used, work_order_id, plant_code, 1 AS level, node_code::text AS path FROM qms.item_node WHERE node_code = #{nodeCode} AND is_deleted = 0 AND plant_code = #{plantCode}
UNION ALL
-- 递归：子节点（parent_id 关联上一层的 id） SELECT child.id, child.node_type, child.node_code, child.parent_id, child.batch_id, child.qty_used, child.work_order_id, child.plant_code, parent.level + 1, parent.path || ' > ' || child.node_code FROM qms.item_node child JOIN trace_tree parent ON child.parent_id = parent.id WHERE child.is_deleted = 0 AND parent.level < #{maxLevel} ) SELECT id, node_type, node_code, parent_id, batch_id, qty_used, work_order_id, plant_code, level, path FROM trace_tree ORDER BY level, id

WITH RECURSIVE trace_up AS ( -- 锚点：起始节点（level=1） SELECT id, node_type, node_code, parent_id, batch_id, qty_used, work_order_id, plant_code, 1 AS level, node_code::text AS path FROM qms.item_node WHERE node_code = #{nodeCode} AND is_deleted = 0 AND plant_code = #{plantCode}
UNION ALL
-- 递归：父节点（parent.id 关联上一层的 parent_id） SELECT parent_node.id, parent_node.node_type, parent_node.node_code, parent_node.parent_id, parent_node.batch_id, parent_node.qty_used, parent_node.work_order_id, parent_node.plant_code, child.level + 1, parent_node.node_code || ' > ' || child.path FROM qms.item_node parent_node JOIN trace_up child ON parent_node.id = child.parent_id WHERE parent_node.is_deleted = 0 AND child.level < #{maxLevel} ) SELECT id, node_type, node_code, parent_id, batch_id, qty_used, work_order_id, plant_code, level, path FROM trace_up ORDER BY level, id
